request.prompt_text:
Find the bug: this binary search sometimes loops forever.

def bs(a, t):
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < t:
            lo = mid
        else:
            hi = mid
    return lo if a and a[lo] == t else -1

